            data: { turbo_frame: dom_id(comment, :new_reaction), action: "dialog#close" } do %>
        <%= image_tag "boost-color.svg", aria: { hidden: true } %>
        <span class="for-screen-reader">Add your own reaction</span>
      <% end %>
    <% end %>
  </div>
<% end %>
